-- NEW integration regression suite, not a replay of the 154 price-core checks.
-- Caller supplies outer BEGIN/ROLLBACK and previously tested core modules.
SET LOCAL TimeZone='UTC';
CREATE SCHEMA price_test;
GRANT USAGE ON SCHEMA price_test TO anon,authenticated,service_role;
CREATE FUNCTION price_test.ok(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $t$
BEGIN
 IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'PRICE_BASICS_ASSERT_FAILED: %',label; END IF;
 RAISE NOTICE 'PRICE_BASICS_PASS: %',label;
END $t$;
CREATE FUNCTION price_test.error(statement text,code text,message text,label text)
RETURNS void LANGUAGE plpgsql AS $t$
DECLARE got_code text; got_message text; before_rows jsonb; after_rows jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) INTO before_rows FROM public.listings l;
 BEGIN EXECUTE statement;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS got_code=RETURNED_SQLSTATE,got_message=MESSAGE_TEXT;
 END;
 SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) INTO after_rows FROM public.listings l;
 PERFORM price_test.ok(got_code IS NOT DISTINCT FROM code
   AND (message IS NULL OR got_message IS NOT DISTINCT FROM message)
   AND before_rows IS NOT DISTINCT FROM after_rows,label);
END $t$;
CREATE TABLE price_test.snapshots(name text PRIMARY KEY,value jsonb NOT NULL);
GRANT ALL ON price_test.snapshots TO authenticated;

