CREATE FUNCTION price_test.reject_title() RETURNS trigger LANGUAGE plpgsql AS $t$
BEGIN IF NEW.title='Injected late failure' THEN RAISE EXCEPTION 'synthetic_after_price_failure' USING ERRCODE='P0001'; END IF; RETURN NEW; END $t$;
CREATE TRIGGER zz_test_late_failure BEFORE UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION price_test.reject_title();
RESET ROLE; SET LOCAL request.jwt.claim.sub='11111111-1111-4111-8111-111111111111'; SET LOCAL request.jwt.claim.role='authenticated'; SET LOCAL ROLE authenticated;
SELECT price_test.error($stmt$SELECT public.save_my_listing_basics_v1('1001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(SELECT value->'basics' FROM price_test.snapshots WHERE name='a2'),'{"title":"Injected late failure","description":"Description","condition":"used"}'::jsonb,'{"kind":"fixed","amount":"999","currency":"EUR"}'::jsonb,'2')$stmt$,'P0001','synthetic_after_price_failure','late_error_rolls_back_price_and_title');
SELECT price_test.ok(((SELECT price_amount=9007199254740993 AND price_revision=2 FROM public.listings WHERE id=1001)),'late_error_keeps_price_revision');
RESET ROLE; DROP TRIGGER zz_test_late_failure ON public.listings;
